+// What a scenario author writes, and the one place a scenario file is validated. A scenario is a JSON script of
+// steps over one session. The runner (run.ts) interprets the steps; the checks (checks.ts) judge the expectations.
+
+import { readFile } from 'node:fs/promises'
+import { isAbsolute, normalize } from 'node:path'
+
+declare const patternBrand: unique symbol
+/** A regex source that compiled. Always matched case-insensitively. */
+export type Pattern = string & { readonly [patternBrand]: true }
+
+/** Argument name to the pattern its value must match: a string as it is, any other value as JSON. */
+export type ArgPatterns = Readonly<Record<string, Pattern>>
+
+/**
+ * One behavior judged on one prompt step. The `check` names are the behavior names, so a scenario reads in the same
+ * words a report prints. Tool names are model-facing `<plugin>__<tool>`; the plugin is the part before `__`.
+ */
+export type Expectation =
+  /** The model enables `plugin` during this prompt. */
+  | { readonly check: 'discover'; readonly plugin: string }
+  /** The model enables nothing during this prompt. */
+  | { readonly check: 'restraint' }
+  /** In the turn right after the model enabled `tool`'s plugin, it calls `tool` with matching args and the call runs. */
+  | { readonly check: 'use'; readonly tool: string; readonly args?: ArgPatterns }
+  /** Dispatch mode. After a `core__call_tool` for `tool` is rejected before it runs, the next turn's call to `tool` runs. */
+  | { readonly check: 'dispatch-recover'; readonly tool: string }
+  /** The final answer matches `matches`, as for an instruction delivered in an enable result. */
+  | { readonly check: 'follow'; readonly matches: Pattern }
+  /** The model loads `skill` (`<plugin>__<skill>`) during this prompt, or does not, as `loaded` says. */
+  | { readonly check: 'skill'; readonly skill: string; readonly loaded: boolean }
+  /**
+   * After a gate denies a call to `tool` with matching args, the model calls neither `tool` with matching args again
+   * nor any tool in `around`, and its answer matches `reports`.
+   */
+  | { readonly check: 'denial'; readonly tool: string; readonly args?: ArgPatterns; readonly reports: Pattern; readonly around?: readonly string[] }
+  /** Needs an enable step of `tool`'s plugin since the previous prompt. The model calls `tool` and the call runs. */
+  | { readonly check: 'host-enable'; readonly tool: string; readonly args?: ArgPatterns }
+  /** Needs a resume step since the previous prompt. The model calls `tool` and the call runs. */
+  | { readonly check: 'resume'; readonly tool: string; readonly args?: ArgPatterns }
+
+export type ScenarioStep =
+  /** `expect` holds the behaviors judged on this prompt, one per check. Invariants need no declaration. */
+  | { readonly kind: 'prompt'; readonly text: string; readonly expect?: readonly Expectation[] }
+  /** A host enable between prompts. */
+  | { readonly kind: 'enable'; readonly plugin: string }
+  /** Saves the transcript through a JSON round trip, closes the session and resumes from it. `plugins` replaces the plugin set. */
+  | { readonly kind: 'resume'; readonly plugins?: readonly string[] }
+
+export interface Scenario {
+  readonly format: 'aigent-scenario/1'
+  /** Plugin directories relative to the scenario file. Each is loaded with loadPlugins and the sets are concatenated. */
+  readonly plugins: readonly string[]
+  /** Enabled at start. Passed again on every resume, where names already enabled are skipped. */
+  readonly enabled?: readonly string[]
+  /**
+   * Env var names holding host secrets. Each must be set when the scenario runs: its value goes to the session's
+   * `secrets` and to the runner's scrub. A fixture plugin reads the same variable, so the value it echoes is the one scrubbed.
+   */
+  readonly secrets?: readonly string[]
+  readonly systemPrompt: string
+  /** Model turns per prompt. The session default applies when absent. */
+  readonly maxTurns?: number
+  /** Non-empty. A step's number, in check ids and result files, is its 1-based position here. */
+  readonly steps: readonly ScenarioStep[]
+}
+
+export class ScenarioError extends Error {
+  readonly problems: readonly string[]
+  constructor(problems: readonly string[]) {
+    super(`invalid scenario:\n- ${problems.join('\n- ')}`)
+    this.problems = problems
+  }
+}
+
+export async function readScenario(file: string): Promise<Scenario> {
+  let value: unknown
+  try {
+    value = JSON.parse(await readFile(file, 'utf8'))
+  } catch (error) {
+    throw new ScenarioError([`${file}: ${error instanceof Error ? error.message : String(error)}`])
+  }
+  return parseScenario(value)
+}
+
+/**
+ * The scenario boundary, also used by readRun for the copy a result directory keeps. Collects every problem, each
+ * at its JSON path, before throwing ScenarioError. Unknown fields are problems too, so a misspelled `expect` is not
+ * silently a scenario without behaviors.
+ */
+export function parseScenario(value: unknown): Scenario {
+  const p = new Problems()
+  const raw = fields(value, '', ['format', 'plugins', 'enabled', 'secrets', 'systemPrompt', 'maxTurns', 'steps'], p)
+  if (raw.format !== 'aigent-scenario/1') p.fail('format: must be "aigent-scenario/1"', undefined)
+  const plugins = directories(raw.plugins, 'plugins', p)
+  const systemPrompt = typeof raw.systemPrompt === 'string' ? raw.systemPrompt : p.fail('systemPrompt: must be a string', '')
+  const maxTurns = raw.maxTurns === undefined || (typeof raw.maxTurns === 'number' && Number.isInteger(raw.maxTurns) && raw.maxTurns > 0) ? raw.maxTurns : p.fail('maxTurns: must be a positive integer', undefined)
+  const rawSteps = Array.isArray(raw.steps) && raw.steps.length > 0 ? (raw.steps as readonly unknown[]) : p.fail('steps: must be a non-empty list', [])
+  const steps: ScenarioStep[] = []
+  for (const [i, raw] of rawSteps.entries()) {
+    const step = parseStep(raw, `steps[${i}]`, steps.slice(steps.findLastIndex((s) => s.kind === 'prompt') + 1), p)
+    if (step) steps.push(step)
+  }
+  const scenario: Scenario = {
+    format: 'aigent-scenario/1',
+    plugins,
+    ...(raw.enabled !== undefined && { enabled: names(raw.enabled, 'enabled', PLUGIN, p) }),
+    ...(raw.secrets !== undefined && { secrets: names(raw.secrets, 'secrets', ENV_NAME, p) }),
+    systemPrompt,
+    ...(maxTurns !== undefined && { maxTurns }),
+    steps,
+  }
+  if (p.list.length > 0) throw new ScenarioError(p.list)
+  return scenario
+}
+
+export interface Names {
+  readonly plugins: readonly string[]
+  readonly tools: readonly string[]
+  readonly skills: readonly string[]
+}
+
+/** Names an expectation relies on, so the runner can refuse a scenario that misspells one before a paid run. */
+export function referencedNames(expectation: Expectation): Names {
+  switch (expectation.check) {
+    case 'discover':
+      return { plugins: [expectation.plugin], tools: [], skills: [] }
+    case 'restraint':
+    case 'follow':
+      return { plugins: [], tools: [], skills: [] }
+    case 'use':
+    case 'dispatch-recover':
+    case 'host-enable':
+    case 'resume':
+      return { plugins: [], tools: [expectation.tool], skills: [] }
+    case 'skill':
+      return { plugins: [], tools: [], skills: [expectation.skill] }
+    case 'denial':
+      return { plugins: [], tools: [expectation.tool, ...(expectation.around ?? [])], skills: [] }
+    default:
+      return expectation satisfies never
+  }
+}
+
+const PLUGIN = /^[a-z0-9-]+$/
+const TOOL = /^[a-z0-9-]+__[A-Za-z0-9_-]+$/
+const SKILL = /^[a-z0-9-]+__[a-z0-9_-]+$/
+const ENV_NAME = /^[A-Z_][A-Z0-9_]*$/
+
+/** `since` holds the steps between the previous prompt and this one. An unknown kind has no value to stand in for it. */
+function parseStep(value: unknown, at: string, since: readonly ScenarioStep[], p: Problems): ScenarioStep | undefined {
+  const kind = isRecord(value) ? value.kind : undefined
+  switch (kind) {
+    case 'prompt': {
+      const raw = fields(value, at, ['kind', 'text', 'expect'], p)
+      const text = typeof raw.text === 'string' && raw.text !== '' ? raw.text : p.fail(`${at}.text: must be a non-empty string`, '')
+      if (raw.expect === undefined) return { kind, text }
+      if (!Array.isArray(raw.expect)) return p.fail(`${at}.expect: must be a list`, { kind, text })
+      const expect: Expectation[] = []
+      for (const [j, e] of (raw.expect as readonly unknown[]).entries()) {
+        const parsed = parseExpectation(e, `${at}.expect[${j}]`, since, p)
+        if (!parsed) continue
+        if (expect.some((other) => other.check === parsed.check)) p.fail(`${at}.expect[${j}]: a second "${parsed.check}" on one step would share its id`, undefined)
+        expect.push(parsed)
+      }
+      return { kind, text, expect }
+    }
+    case 'enable': {
+      const raw = fields(value, at, ['kind', 'plugin'], p)
+      return { kind, plugin: name(raw.plugin, `${at}.plugin`, PLUGIN, p) }
+    }
+    case 'resume': {
+      const raw = fields(value, at, ['kind', 'plugins'], p)
+      return raw.plugins === undefined ? { kind } : { kind, plugins: directories(raw.plugins, `${at}.plugins`, p) }
+    }
+    default:
+      return p.fail(`${at}.kind: must be "prompt", "enable" or "resume"`, undefined)
+  }
+}
+
+type Check = Expectation['check']
+
+/** One parser per check. A check without one fails the build. */
+const expectations: {
+  readonly [K in Check]: (raw: Readonly<Record<string, unknown>>, at: string, since: readonly ScenarioStep[], p: Problems) => Extract<Expectation, { readonly check: K }>
+} = {
+  discover: (raw, at, _, p) => ({ check: 'discover', plugin: name(raw.plugin, `${at}.plugin`, PLUGIN, p) }),
+  restraint: () => ({ check: 'restraint' }),
+  use: (raw, at, _, p) => ({ check: 'use', ...called(raw, at, p) }),
+  'dispatch-recover': (raw, at, _, p) => ({ check: 'dispatch-recover', tool: name(raw.tool, `${at}.tool`, TOOL, p) }),
+  follow: (raw, at, _, p) => ({ check: 'follow', matches: pattern(raw.matches, `${at}.matches`, p) }),
+  skill: (raw, at, _, p) => ({
+    check: 'skill',
+    skill: name(raw.skill, `${at}.skill`, SKILL, p),
+    loaded: typeof raw.loaded === 'boolean' ? raw.loaded : p.fail(`${at}.loaded: must be true or false`, false),
+  }),
+  denial: (raw, at, _, p) => ({
+    check: 'denial',
+    ...called(raw, at, p),
+    reports: pattern(raw.reports, `${at}.reports`, p),
+    ...(raw.around !== undefined && { around: names(raw.around, `${at}.around`, TOOL, p) }),
+  }),
+  'host-enable': (raw, at, since, p) => {
+    const call = called(raw, at, p)
+    const plugin = call.tool.split('__')[0]
+    if (call.tool && !since.some((s) => s.kind === 'enable' && s.plugin === plugin)) p.fail(`${at}: needs an enable step of "${plugin}" since the previous prompt`, undefined)
+    return { check: 'host-enable', ...call }
+  },
+  resume: (raw, at, since, p) => {
+    if (!since.some((s) => s.kind === 'resume')) p.fail(`${at}: needs a resume step since the previous prompt`, undefined)
+    return { check: 'resume', ...called(raw, at, p) }
+  },
+}
+
+/** The fields each check takes besides `check`. */
+const FIELDS: { readonly [K in Check]: readonly string[] } = {
+  discover: ['plugin'],
+  restraint: [],
+  use: ['tool', 'args'],
+  'dispatch-recover': ['tool'],
+  follow: ['matches'],
+  skill: ['skill', 'loaded'],
+  denial: ['tool', 'args', 'reports', 'around'],
+  'host-enable': ['tool', 'args'],
+  resume: ['tool', 'args'],
+}
+
+function parseExpectation(value: unknown, at: string, since: readonly ScenarioStep[], p: Problems): Expectation | undefined {
+  const check = isRecord(value) ? value.check : undefined
+  if (typeof check !== 'string' || !Object.hasOwn(expectations, check)) return p.fail(`${at}.check: must be one of ${Object.keys(expectations).join(', ')}`, undefined)
+  return expectations[check as Check](fields(value, at, ['check', ...FIELDS[check as Check]], p), at, since, p)
+}
+
+/** `tool` and optional `args`, shared by the checks about one call. */
+function called(raw: Readonly<Record<string, unknown>>, at: string, p: Problems): { readonly tool: string; readonly args?: ArgPatterns } {
+  const tool = name(raw.tool, `${at}.tool`, TOOL, p)
+  if (raw.args === undefined) return { tool }
+  if (!isRecord(raw.args)) return p.fail(`${at}.args: must be an object of patterns`, { tool })
+  return { tool, args: Object.fromEntries(Object.entries(raw.args).map(([k, v]) => [k, pattern(v, `${at}.args.${k}`, p)])) }
+}
+
+/** Every problem of one parse. `fail` records one and hands back a placeholder, so a single pass finds them all. */
+class Problems {
+  readonly list: string[] = []
+  fail<T>(problem: string, placeholder: T): T {
+    this.list.push(problem)
+    return placeholder
+  }
+}
+
+function fields(value: unknown, at: string, known: readonly string[], p: Problems): Readonly<Record<string, unknown>> {
+  if (!isRecord(value)) return p.fail(`${at || 'scenario'}: must be an object`, {})
+  for (const key of Object.keys(value)) if (!known.includes(key)) p.fail(`${at ? `${at}.` : ''}${key}: unknown field`, undefined)
+  return value
+}
+
+function name(value: unknown, at: string, shape: RegExp, p: Problems): string {
+  return typeof value === 'string' && shape.test(value) ? value : p.fail(`${at}: must match ${shape.source}`, '')
+}
+
+function names(value: unknown, at: string, shape: RegExp, p: Problems): readonly string[] {
+  return Array.isArray(value) ? value.map((v: unknown, i) => name(v, `${at}[${i}]`, shape, p)) : p.fail(`${at}: must be a list`, [])
+}
+
+/** Non-empty, relative and inside the scenario's directory, because a multeval case carries only that directory. */
+function directories(value: unknown, at: string, p: Problems): readonly string[] {
+  if (!Array.isArray(value) || value.length === 0) return p.fail(`${at}: must be a non-empty list of directories`, [])
+  return value.map((dir: unknown, i) =>
+    typeof dir === 'string' && dir !== '' && !isAbsolute(dir) && normalize(dir).split(/[\\/]/)[0] !== '..' ? dir : p.fail(`${at}[${i}]: must be a directory inside the scenario's own`, ''),
+  )
+}
+
+function pattern(value: unknown, at: string, p: Problems): Pattern {
+  if (typeof value !== 'string') return p.fail(`${at}: must be a regex source`, '' as Pattern)
+  try {
+    new RegExp(value, 'i')
+  } catch (error) {
+    p.fail(`${at}: does not compile: ${error instanceof Error ? error.message : String(error)}`, undefined)
+  }
+  return value as Pattern
+}
+
+function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
+  return typeof value === 'object' && value !== null && !Array.isArray(value)
+}

+ */
+export async function writeRun(dir: string, run: RunLog): Promise<void> {
+  // Checked first, because rename silently replaces an empty directory.
+  if (await exists(dir)) throw new Error(`${dir} already exists`)
+  await mkdir(dirname(dir), { recursive: true })
+  const tmp = `${dir}.partial-${randomUUID()}`
+  await mkdir(tmp)
+  try {
+    const { steps, transcript, ...head } = run
+    const file: RunFile = {
+      ...head,
+      steps: steps.map((step) => {
+        switch (step.kind) {
+          case 'prompt':
+            return { kind: step.kind, result: step.result, end: step.end }
+          case 'enable':
+          case 'resume':
+            return { kind: step.kind, end: step.end }
+          default:
+            return step satisfies never
+        }
+      }),
+    }
+    const lines = steps.flatMap((step, i) => (step.kind === 'resume' ? [] : step.events.map((event) => `${JSON.stringify({ step: i + 1, event })}\n`)))
+    await writeFile(join(tmp, RUN_FILE), `${JSON.stringify(file, null, 2)}\n`)
+    await writeFile(join(tmp, TRANSCRIPT_FILE), `${JSON.stringify(transcript)}\n`)
+    await writeFile(join(tmp, EVENTS_FILE), lines.join(''))
+    for (const [i, step] of steps.entries()) if (step.kind === 'resume') await writeFile(join(tmp, resumeFile(i + 1)), `${JSON.stringify(step.saved)}\n`)
+    await rename(tmp, dir)
+  } catch (error) {
+    await rm(tmp, { recursive: true, force: true })
+    throw error
+  }
+}
+
+export class RunFileError extends Error {
+  readonly problems: readonly string[]
+  constructor(dir: string, problems: readonly string[]) {
+    super(`${dir} is not an aigent-run/1 result directory:\n- ${problems.join('\n- ')}`)
+    this.problems = problems
+  }
+}
+
+/**
+ * The result-directory boundary, for `aigent check` and the future multeval grader. Parses what writeRun wrote
+ * back into the identical RunLog, and throws RunFileError naming every problem rather than guessing. Past the
+ * type tag of each event, events and transcript messages are trusted as written.
+ */
+export async function readRun(dir: string): Promise<RunLog> {
+  const problems: string[] = []
+  const read = async (name: string): Promise<string | undefined> => {
+    try {
+      return await readFile(join(dir, name), 'utf8')
+    } catch (error) {
+      problems.push(`${name}: ${messageOf(error)}`)
+      return undefined
+    }
+  }
+  const json = async (name: string): Promise<unknown> => {
+    const text = await read(name)
+    if (text === undefined) return undefined
+    try {
+      return JSON.parse(text)
+    } catch (error) {
+      problems.push(`${name}: ${messageOf(error)}`)
+      return undefined
+    }
+  }
+  const transcriptIn = async (name: string): Promise<Transcript> => {
+    const value = await json(name)
+    if (isRecord(value) && value.format === 'aigent-transcript/1' && Array.isArray(value.messages)) return value as unknown as Transcript
+    if (value !== undefined) problems.push(`${name}: not an aigent-transcript/1 transcript`)
+    return { format: 'aigent-transcript/1', messages: [] }
+  }
+
+  const head = parseRunFile(await json(RUN_FILE), problems)
+  const transcript = await transcriptIn(TRANSCRIPT_FILE)
+  const events = new Map<number, SessionEvent[]>()
+  const lines = (await read(EVENTS_FILE))?.split('\n') ?? []
+  let previous = 1
+  for (const [i, line] of lines.entries()) {
+    if (line === '' && i === lines.length - 1) continue
+    const at = `${EVENTS_FILE} line ${i + 1}`
+    let value: unknown
+    try {
+      value = JSON.parse(line)
+    } catch (error) {
+      problems.push(`${at}: ${messageOf(error)}`)
+      continue
+    }
+    const step = isRecord(value) ? value.step : undefined
+    const event = isRecord(value) ? value.event : undefined
+    const ran = typeof step === 'number' ? head?.steps[step - 1] : undefined
+    if (typeof step !== 'number' || !ran || ran.kind === 'resume' || step < previous) {
+      problems.push(`${at}: "step" must name a prompt or enable step that ran, in order`)
+      continue
+    }
+    if (!isRecord(event) || typeof event.type !== 'string' || !EVENT_TYPES.has(event.type) || Object.keys(value as object).length !== 2) {
+      problems.push(`${at}: must be {"step", "event"} with a known event type`)
+      continue
+    }
+    previous = step
+    const list = events.get(step) ?? []
+    list.push(event as unknown as SessionEvent)
+    events.set(step, list)
+  }
+  const saved = new Map<number, Transcript>()
+  for (const [i, step] of (head?.steps ?? []).entries()) if (step.kind === 'resume') saved.set(i + 1, await transcriptIn(resumeFile(i + 1)))
+  if (head && (head.steps.at(-1)?.end ?? head.start) > transcript.messages.length) problems.push(`${TRANSCRIPT_FILE}: shorter than the last step's end`)
+  if (!head || problems.length > 0) throw new RunFileError(dir, problems)
+
+  const steps = head.steps.map((step, i): StepLog => {
+    switch (step.kind) {
+      case 'prompt':
+        return { kind: step.kind, result: step.result, events: events.get(i + 1) ?? [], end: step.end }
+      case 'enable':
+        return { kind: step.kind, events: events.get(i + 1) ?? [], end: step.end }
+      case 'resume':
+        return { kind: step.kind, saved: saved.get(i + 1)!, end: step.end }
+      default:
+        return step satisfies never
+    }
+  })
+  return { ...head, steps, transcript }
+}
+
+const EVENT_TYPES = new Set<string>(['text', 'tool_start', 'tool_end', 'record', 'turn_end'] satisfies SessionEvent['type'][])
+
+/** run.json against the scenario it carries: each step the kind its scenario step is, ends that never shrink, and a run that stops only where it may. */
+function parseRunFile(value: unknown, problems: string[]): RunFile | undefined {
+  if (value === undefined) return undefined
+  if (!isRecord(value) || value.format !== 'aigent-run/1') {
+    problems.push(`${RUN_FILE}: format must be "aigent-run/1"`)
+    return undefined
+  }
+  const fail = (problem: string): void => {
+    problems.push(`${RUN_FILE}: ${problem}`)
+  }
+  const known = ['format', 'scenario', 'model', 'toolMode', 'start', 'steps', 'failure']
+  for (const key of Object.keys(value)) if (!known.includes(key)) fail(`unknown field "${key}"`)
+  let scenario: Scenario | undefined
+  try {
+    scenario = parseScenario(value.scenario)
+  } catch (error) {
+    if (!(error instanceof ScenarioError)) throw error
+    for (const problem of error.problems) fail(`scenario: ${problem}`)
+  }
+  if (!isModelSpec(value.model)) fail('model is not a ModelSpec')
+  if (value.toolMode !== 'native' && value.toolMode !== 'dispatch') fail('toolMode must be "native" or "dispatch"')
+  if (!isCount(value.start)) fail('start must be a non-negative integer')
+  if (!Array.isArray(value.steps)) fail('steps must be a list')
+  if (!scenario || !isCount(value.start) || !Array.isArray(value.steps)) return undefined
+
+  const steps: readonly unknown[] = value.steps
+  if (steps.length > scenario.steps.length) fail(`${steps.length} steps ran but the scenario has ${scenario.steps.length}`)
+  let end = value.start
+  for (const [i, step] of steps.entries()) {
+    const kind = scenario.steps[i]?.kind
+    if (!isRecord(step) || step.kind !== kind) {
+      fail(`steps[${i}] must be a ${kind ?? 'missing'} step, as the scenario's step ${i + 1} is`)
+      continue
+    }
+    const fields = kind === 'prompt' ? ['kind', 'result', 'end'] : ['kind', 'end']
+    if (Object.keys(step).some((k) => !fields.includes(k))) fail(`steps[${i}] fields must be ${fields.join(', ')}`)
+    if (!isCount(step.end) || step.end < end) fail(`steps[${i}].end must be an integer no smaller than the one before`)
+    else end = step.end
+    if (kind !== 'prompt') continue
+    if (!isRunResult(step.result)) fail(`steps[${i}].result is not a RunResult`)
+    else if (i < steps.length - 1 && (step.result.stop === 'error' || step.result.stop === 'aborted')) fail(`steps[${i}] ended ${step.result.stop}, so no step may follow it`)
+  }
+  const { failure } = value
+  const failed = isRecord(failure) && failure.step === steps.length + 1 && failure.step <= scenario.steps.length && typeof failure.message === 'string' && Object.keys(failure).length === 2
+  if (failure !== undefined && !failed) fail('failure must be {"step", "message"} naming the step after the last that ran')
+  return problems.length > 0 ? undefined : { ...(value as unknown as RunFile), scenario }
+}
+
+function isModelSpec(value: unknown): value is ModelSpec {
+  if (!isRecord(value) || typeof value.id !== 'string') return false
+  const optional = (key: string, type: 'boolean' | 'number'): boolean => value[key] === undefined || typeof value[key] === type
+  switch (value.kind) {
+    case 'builtin':
+      return typeof value.provider === 'string'
+    case 'openai-compatible':
+      return typeof value.baseUrl === 'string' && typeof value.apiKeyEnv === 'string' && optional('reasoning', 'boolean') && optional('contextWindow', 'number') && optional('maxTokens', 'number')
+    default:
+      return false
+  }
+}
+
+function isRunResult(value: unknown): value is RunResult {
+  if (!isRecord(value) || !isCount(value.turns)) return false
+  switch (value.stop) {
+    case 'done':
+    case 'max_turns':
+      return typeof value.text === 'string'
+    case 'aborted':
+      return true
+    case 'error':
+      return typeof value.message === 'string'
+    default:
+      return false
+  }
+}
+
+function isCount(value: unknown): value is number {
+  return typeof value === 'number' && Number.isInteger(value) && value >= 0
+}
+
+function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
+  return typeof value === 'object' && value !== null && !Array.isArray(value)
+}
+
+async function exists(path: string): Promise<boolean> {
+  try {
+    await stat(path)
+    return true
+  } catch (error) {
+    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return false
+    throw error
+  }
+}

// How a run is judged. Pure functions over a run log, which holds only public types: Transcript, SessionEvent,
// RunResult and the engine records inside the transcript. Invariants are engine properties every run must keep.
// Behaviors are bets on the model, measured as rates over trials. Cost is reported and never judged.

import { isDeepStrictEqual } from 'node:util'
import type { JsonObject, JsonValue, ToolResultSnapshot } from '../plugin.ts'
import type { EngineRecord, RunResult, SessionEvent, ToolMode, Transcript } from '../session.ts'
import { leaksIn, type RunLog } from './run.ts'
import type { ArgPatterns, Expectation, Pattern } from './scenario.ts'

export type Verdict =
  | { readonly kind: 'pass'; readonly evidence: JsonObject }
  | { readonly kind: 'fail'; readonly evidence: JsonObject }
  /** The behavior had no chance to show: its precondition never happened, or its step did not run. Left out of rates. */
  | { readonly kind: 'skip'; readonly why: string }

/** An invariant has nothing to wait for, so it never skips. A run with nothing to check passes. */
export type InvariantVerdict = Extract<Verdict, { readonly kind: 'pass' | 'fail' }>

export interface BehaviorResult {
  /** `${check}@${step}`, unique within a scenario: the metric name a report and a future grade use. */
  readonly id: string
  readonly check: Expectation['check']
  /** 1-based scenario step. */
  readonly step: number
  readonly verdict: Verdict
}

export interface RequestCost {
  /** input + cacheRead + cacheWrite. */
  readonly promptTokens: number
  readonly cachedTokens: number
  readonly outputTokens: number
  /** cachedTokens / promptTokens, two decimals, 0 for an empty prompt. */
  readonly cachedRatio: number
}

export interface Cost {
  /** One entry per prompt step that ran. */
  readonly steps: readonly { readonly step: number; readonly turns: number; readonly requests: readonly RequestCost[] }[]
  readonly turns: number
  readonly promptTokens: number
  readonly outputTokens: number
  /** Sum of cachedTokens over sum of promptTokens across every request of the run. */
  readonly cachedRatio: number
}

export interface Report {
  /** Every scenario step ran. False when a prompt ended `error` or `aborted`, or a step threw. */
  readonly complete: boolean
  readonly invariants: { readonly [K in Invariant]: InvariantVerdict }
  /** One per expectation, in scenario order. */
  readonly behaviors: readonly BehaviorResult[]
  readonly cost: Cost
}

/** The one entry point for every caller: the live test, `aigent run`, `aigent check`, and later the multeval grader. */
export function check(run: RunLog): Report {
  const view = viewOf(run)
  return {
    complete: run.steps.length === run.scenario.steps.length,
    invariants: Object.fromEntries(Object.entries(invariants).map(([name, holds]) => [name, holds(view)])) as Report['invariants'],
    behaviors: run.scenario.steps.flatMap((step, i) => (step.kind === 'prompt' ? (step.expect ?? []).map((e) => behavior(e, i + 1, view)) : [])),
    cost: costOf(view),
  }
}

// ---------------------------------------------------------------------------------------------------------------
// The transcript, read once. The only code in the repo outside src/pi.ts that knows pi's message shapes.

/** The parts of an `aigent-transcript/1` message the checks read. One per message, so step bounds index both. */
type Entry =
  | { readonly role: 'system' }
  | { readonly role: 'user'; readonly text: string }
  | { readonly role: 'assistant'; readonly calls: readonly Call[]; readonly usage: Usage | undefined }
  | { readonly role: 'toolResult'; readonly callId: string; readonly isError: boolean; readonly text: string }
  | { readonly role: 'record'; readonly record: EngineRecord }

interface Call {
  readonly id: string
  readonly name: string
  readonly args: JsonObject
}

interface Usage {
  readonly input: number
  readonly output: number
  readonly cacheRead: number
  readonly cacheWrite: number
}

/**
 * system, user (string or text parts), assistant (text, thinking and toolCall parts, usage), toolResult (toolCallId,
 * isError, text parts), aigent (an engine record). Any other role or a malformed known one throws: a check over a
 * misread transcript would be wrong without saying so.
 */
function entriesOf(transcript: Transcript): readonly Entry[] {
  return transcript.messages.map((message, i): Entry => {
    const fail = (why: string): never => {
      throw new Error(`transcript message ${i}: ${why}`)
    }
    if (!isObject(message)) return fail('not an object')
    switch (message.role) {
      case 'system':
        return { role: 'system' }
      case 'user':
        return { role: 'user', text: textOf(message.content) ?? fail('content is not text') }
      case 'assistant': {
        if (!Array.isArray(message.content)) return fail('content is not a list')
        const calls = message.content.flatMap((part): Call[] => {
          if (!isObject(part)) return fail('a content part is not an object')
          if (part.type === 'toolCall') return typeof part.id === 'string' && typeof part.name === 'string' && isObject(part.arguments) ? [{ id: part.id, name: part.name, args: part.arguments }] : fail('a malformed tool call')
          return part.type === 'text' || part.type === 'thinking' ? [] : fail(`an unknown content part ${JSON.stringify(part.type)}`)
        })
        const usage = message.usage
        const counted = isObject(usage) && [usage.input, usage.output, usage.cacheRead, usage.cacheWrite].every((n) => typeof n === 'number')
        return { role: 'assistant', calls, usage: counted ? (usage as unknown as Usage) : undefined }
      }
      case 'toolResult': {
        const text = textOf(message.content)
        if (typeof message.toolCallId !== 'string' || typeof message.isError !== 'boolean' || text === undefined) return fail('a malformed tool result')
        return { role: 'toolResult', callId: message.toolCallId, isError: message.isError, text }
      }
      case 'aigent':
        return { role: 'record', record: recordOf(message.record) ?? fail('not an engine record') }
      default:
        return fail(`unknown role ${JSON.stringify(message.role)}`)
    }
  })
}

function textOf(content: JsonValue | undefined): string | undefined {
  if (typeof content === 'string') return content
  if (!Array.isArray(content)) return undefined
  const parts = content.filter(isObject)
  return parts.length === content.length ? parts.flatMap((p) => (p.type === 'text' && typeof p.text === 'string' ? [p.text] : [])).join('') : undefined
}

function recordOf(value: JsonValue | undefined): EngineRecord | undefined {
  if (!isObject(value)) return undefined
  const strings = (...keys: string[]): boolean => keys.every((k) => typeof value[k] === 'string')
  const cause = value.cause
  const valid =
    (value.kind === 'enabled' && strings('plugin') && (cause === 'initial' || cause === 'host' || cause === 'model' || (isObject(cause) && typeof cause.dependencyOf === 'string'))) ||
    (value.kind === 'denied' && strings('callId', 'tool', 'plugin', 'reason')) ||
    (value.kind === 'catalog' && strings('fingerprint')) ||
    (value.kind === 'pending' && strings('text')) ||
    value.kind === 'delivered'
  // The brands mean "in the catalog", which the engine checked when it wrote the record.
  return valid ? (value as unknown as EngineRecord) : undefined
}

/** A run parsed once for every check. */
interface RunView {
  readonly log: RunLog
  /** The final transcript. */
  readonly entries: readonly Entry[]
  /** Per step that ran, the transcript entries it added. */
  readonly added: readonly (readonly Entry[])[]
  /**
   * One per session: the plugins enabled when it was created, read from the transcript because no listener saw
   * those records, and the events of its steps in emission order, each tagged with its step number.
   */
  readonly sessions: readonly { readonly enabledAtStart: ReadonlySet<string>; readonly events: readonly Tagged[] }[]
  /** Keyed by 1-based step number. Only prompt steps that ran and ended `done` or `max_turns`. */
  readonly prompts: ReadonlyMap<number, PromptView>
}

interface Tagged {
  readonly step: number
  readonly event: SessionEvent
}

interface PromptView {
  readonly toolMode: ToolMode
  readonly events: readonly SessionEvent[]
  readonly result: Extract<RunResult, { readonly stop: 'done' | 'max_turns' }>
  /** The transcript entries this prompt added. */
  readonly entries: readonly Entry[]
  /** The entries before this prompt. */
  readonly before: readonly Entry[]
}

function viewOf(log: RunLog): RunView {
  const entries = entriesOf(log.transcript)
  const bounds = [log.start, ...log.steps.map((s) => s.end)]
  const added = log.steps.map((_, i) => entries.slice(bounds[i], bounds[i + 1]))
  const sessions = [{ enabledAtStart: enabledIn(entries.slice(0, log.start)), events: [] as Tagged[] }]
  const prompts = new Map<number, PromptView>()
  for (const [i, step] of log.steps.entries()) {
    switch (step.kind) {
      case 'prompt': {
        const { result } = step
        if (result.stop === 'done' || result.stop === 'max_turns') {
          prompts.set(i + 1, { toolMode: log.toolMode, events: step.events, result, entries: added[i]!, before: entries.slice(0, bounds[i]) })
        }
        sessions.at(-1)!.events.push(...step.events.map((event) => ({ step: i + 1, event })))
        break
      }
      case 'enable':
        sessions.at(-1)!.events.push(...step.events.map((event) => ({ step: i + 1, event })))
        break
      case 'resume':
        sessions.push({ enabledAtStart: enabledIn(entries.slice(0, step.end)), events: [] })
        break
      default:
        step satisfies never
    }
  }
  return { log, entries, added, sessions, prompts }
}

// ---------------------------------------------------------------------------------------------------------------
// Invariants. One failing run is an engine bug. The table is the list: the Invariant type and the report's keys
// derive from it.

const invariants = {
  /** No string anywhere in the run log, keys and the scenario included, carries a scrub mark. */
  'secret-free': (run: RunView): InvariantVerdict => {
    const leaks: { readonly path: string; readonly secret: string }[] = []
    strings(run.log, '', (path, text) => leaks.push(...leaksIn(text).map((secret) => ({ path, secret }))))
    return leaks.length === 0 ? pass({}) : fail({ secrets: [...new Set(leaks.map((l) => l.secret))].sort(), paths: leaks.slice(0, 20).map((l) => l.path) })
  },

  /** Per session, no tool_start of a plugin's tool comes before an enabled record for that plugin. */
  'enabled-before-call': (run: RunView): InvariantVerdict => {
    const violations: JsonObject[] = []
    let calls = 0
    for (const session of run.sessions) {
      const enabled = new Set(session.enabledAtStart)
      for (const { step, event } of session.events) {
        if (event.type === 'record' && event.record.kind === 'enabled') enabled.add(event.record.plugin)
        if (event.type !== 'tool_start' || event.call.plugin === 'core') continue
        calls += 1
        if (!enabled.has(event.call.plugin)) violations.push({ step, tool: event.call.name })
      }
    }
    return violations.length > 0 ? fail({ violations }) : pass({ calls })
  },

  /**
   * At each resume, the final transcript begins with the saved messages unchanged (no record lost or rewritten),
   * and no later enabled record names a plugin the saved records had enabled.
   */
  'resume-keeps-plugins': (run: RunView): InvariantVerdict => {
    const violations: JsonObject[] = []
    let resumes = 0
    for (const [i, step] of run.log.steps.entries()) {
      if (step.kind !== 'resume') continue
      resumes += 1
      const saved = step.saved.messages
      if (!isDeepStrictEqual(run.log.transcript.messages.slice(0, saved.length), saved)) violations.push({ step: i + 1, kind: 'prefix' })
      const was = enabledIn(entriesOf(step.saved))
      for (const entry of run.entries.slice(saved.length)) {
        if (entry.role === 'record' && entry.record.kind === 'enabled' && was.has(entry.record.plugin)) violations.push({ step: i + 1, kind: 're-enabled', plugin: entry.record.plugin })
      }
    }
    return violations.length > 0 ? fail({ violations }) : pass({ resumes })
  },

  /** Every denial a tool_end reports has a denied record with the same call id, tool and gate plugin in the final transcript. */
  'denial-recorded': (run: RunView): InvariantVerdict => {
    const key = (callId: string, tool: string, plugin: string): string => JSON.stringify([callId, tool, plugin])
    const recorded = new Set(run.entries.flatMap((e) => (e.role === 'record' && e.record.kind === 'denied' ? [key(e.record.callId, e.record.tool, e.record.plugin)] : [])))
    const missing: JsonObject[] = []
    let denials = 0
    for (const { step, event } of run.sessions.flatMap((s) => s.events)) {
      if (event.type !== 'tool_end' || event.result.outcome.kind !== 'denied') continue
      const { call } = event.result
      for (const denial of event.result.outcome.denials) {
        denials += 1
        if (!recorded.has(key(call.id, call.name, denial.plugin))) missing.push({ step, tool: call.name, plugin: denial.plugin })
      }
    }
    return missing.length > 0 ? fail({ missing }) : pass({ denials })
  },

  /**
   * Each pending record's text is in the first user message after it and in no other user message. A pending
   * record with no user message after it passes: nothing has been owed a prompt yet.
   */
  'enable-text-once': (run: RunView): InvariantVerdict => {
    const violations: JsonObject[] = []
    let pending = 0
    for (const [i, entry] of run.entries.entries()) {
      if (entry.role !== 'record' || entry.record.kind !== 'pending') continue
      pending += 1
      const { text } = entry.record
      const users = run.entries.slice(i + 1).flatMap((e) => (e.role === 'user' ? [e.text] : []))
      if (users.length === 0) continue
      const delivered = users.filter((u) => u.includes(text)).length
      const first = users[0]!.includes(text)
      if (delivered !== 1 || !first) violations.push({ delivered, first })
    }
    return violations.length > 0 ? fail({ violations }) : pass({ pending })
  },
} satisfies Record<string, (run: RunView) => InvariantVerdict>

export type Invariant = keyof typeof invariants

// ---------------------------------------------------------------------------------------------------------------
// Behaviors. Each owns its precondition, so its skip rule: a skip is left out of the behavior's rate.

function behavior(expectation: Expectation, step: number, run: RunView): BehaviorResult {
  const ran = run.log.steps[step - 1]
  const prompt = run.prompts.get(step)
  const { failure } = run.log
  const verdict: Verdict = prompt
    ? judge(expectation, prompt)
    : ran?.kind === 'prompt'
      ? skip(`the prompt ended ${ran.result.stop}`)
      : skip(failure ? `step ${failure.step} threw: ${failure.message}` : 'an earlier prompt ended the run')
  return { id: `${expectation.check}@${step}`, check: expectation.check, step, verdict }
}

/** A check without a judge fails the build. */
function judge(e: Expectation, step: PromptView): Verdict {
  switch (e.check) {
    case 'discover': {
      if (enabledIn(step.before).has(e.plugin)) return skip(`${e.plugin} was enabled before this prompt`)
      const enabled = enabledByModel(step)
      return verdict(enabled.includes(e.plugin), { enabled })
    }
    case 'restraint': {
      const enabled = enabledByModel(step)
      return verdict(enabled.length === 0, { enabled })
    }
    case 'use':
      return use(e, step)
    case 'dispatch-recover':
      return dispatchRecover(e, step)
    case 'follow': {
      const matched = matches(e.matches, step.result.text)
      return verdict(matched, { matched, answer: step.result.text.slice(0, 300) })
    }
    case 'skill': {
      const plugin = pluginOf(e.skill)
      if (!enabledIn([...step.before, ...step.entries]).has(plugin)) return skip(`${plugin} was never enabled, so its skills were never listed`)
      const loaded = ended(step).some((r) => r.call.name === 'core__load_skill' && r.call.args.name === e.skill && ran(r))
      return verdict(loaded === e.loaded, { loaded })
    }
    case 'denial':
      return denial(e, step)
    case 'host-enable':
    case 'resume': {
      const calls = ended(step)
      return verdict(calls.some((r) => r.call.name === e.tool && argsMatch(r.call.args, e.args) && ran(r)), { calls: calls.map(callEvidence) })
    }
    default:
      return e satisfies never
  }
}

/** The turn right after the model enabled the tool's plugin must call it. */
function use(e: Extract<Expectation, { readonly check: 'use' }>, step: PromptView): Verdict {
  const plugin = pluginOf(e.tool)
  const at = step.events.findIndex((ev) => ev.type === 'record' && ev.record.kind === 'enabled' && ev.record.plugin === plugin && ev.record.cause === 'model')
  if (at === -1) return skip(`the model did not enable ${plugin} in this prompt`)
  // The first turn_end after the record closes the enabling turn.
  const next = step.events.slice(at).flatMap((ev) => (ev.type === 'turn_end' ? [ev.turn] : []))[1]
  const calls = next?.calls ?? []
  return verdict(
    calls.some((r) => r.call.name === e.tool && argsMatch(r.call.args, e.args) && ran(r)),
    { turn: next?.turn ?? null, calls: calls.map(callEvidence) },
  )
}

/**
 * A call rejected before it ran has no tool_start, only an error result in the transcript under the same id. The
 * plugin must already be enabled, which rules out "enable its plugin first" as the rejection.
 */
function dispatchRecover(e: Extract<Expectation, { readonly check: 'dispatch-recover' }>, step: PromptView): Verdict {
  if (step.toolMode === 'native') return skip('native mode declares the tool, so no core__call_tool needs recovering')
  const plugin = pluginOf(e.tool)
  const started = new Set(step.events.flatMap((ev) => (ev.type === 'tool_start' ? [ev.call.id] : [])))
  const results = new Map(step.entries.flatMap((en) => (en.role === 'toolResult' ? [[en.callId, en] as const] : [])))
  const finished = new Map(ended(step).map((r) => [r.call.id, r] as const))
  for (const [i, entry] of step.entries.entries()) {
    if (entry.role !== 'assistant') continue
    const rejected = entry.calls.find((c) => c.name === 'core__call_tool' && c.args.tool === e.tool && results.get(c.id)?.isError === true && !started.has(c.id))
    if (!rejected || !enabledIn([...step.before, ...step.entries.slice(0, i)]).has(plugin)) continue
    const next = step.entries.slice(i + 1).find((en) => en.role === 'assistant')
    const retried = (next?.role === 'assistant' ? next.calls : []).map((c) => {
      const result = finished.get(c.id)
      return result ? callEvidence(result) : { name: c.name, args: c.args, ran: false }
    })
    return verdict(retried.some((r) => r.name === e.tool && r.ran), { error: results.get(rejected.id)!.text.slice(0, 200), retried })
  }
  return skip(`no core__call_tool for ${e.tool} was rejected before it ran`)
}

function denial(e: Extract<Expectation, { readonly check: 'denial' }>, step: PromptView): Verdict {
  const first = step.events.findIndex((ev) => ev.type === 'tool_end' && ev.result.call.name === e.tool && argsMatch(ev.result.call.args, e.args) && ev.result.outcome.kind === 'denied')
  if (first === -1) return skip('no matching call was denied')
  const later = step.events.slice(first + 1).flatMap((ev) => (ev.type === 'tool_start' ? [ev.call] : []))
  const retries = later.filter((c) => c.name === e.tool && argsMatch(c.args, e.args)).map((c) => c.args)
  const routes = later.filter((c) => e.around?.includes(c.name)).map((c) => c.name)
  const reported = matches(e.reports, step.result.text)
  return verdict(retries.length === 0 && routes.length === 0 && reported, { retries, routes, reported, answer: step.result.text.slice(0, 300) })
}

// ---------------------------------------------------------------------------------------------------------------

/** Per prompt step that ran: requests are the assistant entries it added that carry usage; turns come from its RunResult. */
function costOf(run: RunView): Cost {
  const steps = run.log.steps.flatMap((step, i) => {
    if (step.kind !== 'prompt') return []
    const requests = run.added[i]!.flatMap((e) => {
      if (e.role !== 'assistant' || !e.usage) return []
      const promptTokens = e.usage.input + e.usage.cacheRead + e.usage.cacheWrite
      return [{ promptTokens, cachedTokens: e.usage.cacheRead, outputTokens: e.usage.output, cachedRatio: ratio(e.usage.cacheRead, promptTokens) }]
    })
    return [{ step: i + 1, turns: step.result.turns, requests }]
  })
  const requests = steps.flatMap((s) => s.requests)
  const promptTokens = sum(requests.map((r) => r.promptTokens))
  return {
    steps,
    turns: sum(steps.map((s) => s.turns)),
    promptTokens,
    outputTokens: sum(requests.map((r) => r.outputTokens)),
    cachedRatio: ratio(sum(requests.map((r) => r.cachedTokens)), promptTokens),
  }
}

const pass = (evidence: JsonObject): InvariantVerdict => ({ kind: 'pass', evidence })
const fail = (evidence: JsonObject): InvariantVerdict => ({ kind: 'fail', evidence })
const skip = (why: string): Verdict => ({ kind: 'skip', why })
const verdict = (ok: boolean, evidence: JsonObject): InvariantVerdict => (ok ? pass(evidence) : fail(evidence))

const pluginOf = (name: string): string => name.slice(0, name.indexOf('__'))
const matches = (pattern: Pattern, text: string): boolean => new RegExp(pattern, 'i').test(text)
const sum = (ns: readonly number[]): number => ns.reduce((a, b) => a + b, 0)
const ratio = (part: number, whole: number): number => (whole > 0 ? Math.round((part / whole) * 100) / 100 : 0)

const ended = (step: PromptView): readonly ToolResultSnapshot[] => step.events.flatMap((ev) => (ev.type === 'tool_end' ? [ev.result] : []))
const ran = (r: ToolResultSnapshot): boolean => r.outcome.kind === 'ran' && !r.outcome.result.isError
const callEvidence = (r: ToolResultSnapshot) => ({ name: r.call.name, args: r.call.args, ran: ran(r) })

/** The plugins the model enabled itself during the prompt, in order. Dependencies it pulled in are not its choice. */
const enabledByModel = (step: PromptView): readonly string[] =>
  step.events.flatMap((ev) => (ev.type === 'record' && ev.record.kind === 'enabled' && ev.record.cause === 'model' ? [ev.record.plugin] : []))

function enabledIn(entries: readonly Entry[]): ReadonlySet<string> {
  return new Set(entries.flatMap((e) => (e.role === 'record' && e.record.kind === 'enabled' ? [e.record.plugin] : [])))
}

/** Every pattern matches the argument of its name: a string as it is, any other value as JSON. A missing argument fails. */
function argsMatch(args: JsonObject, patterns: ArgPatterns | undefined): boolean {
  return Object.entries(patterns ?? {}).every(([name, pattern]) => {
    const value = args[name]
    return value !== undefined && matches(pattern, typeof value === 'string' ? value : JSON.stringify(value))
  })
}

/** Calls `visit` with every string in `value`, object keys included, at its JSON path. */
function strings(value: unknown, path: string, visit: (path: string, text: string) => void): void {
  if (typeof value === 'string') visit(path, value)
  else if (Array.isArray(value)) value.forEach((v, i) => strings(v, `${path}[${i}]`, visit))
  else if (typeof value === 'object' && value !== null) {
    for (const [k, v] of Object.entries(value)) {
      const at = path ? `${path}.${k}` : k
      visit(at, k)
      strings(v, at, visit)
    }
  }
}

function isObject(value: JsonValue | undefined): value is JsonObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

